function downloadCgit() {
    // Base64 解码
    const data = Uint8Array.from(atob(window.cgitBase64), c => c.charCodeAt(0));
    // 自动下载
    const a = Object.assign(document.createElement('a'), { href: URL.createObjectURL(new Blob([data])), download: 'cgit.zip' });
    a.click();URL.revokeObjectURL(a.href);
}

window.cgitBase64 = ``